    body = `<div class="ai-storage-page"><div class="ai-page-heading"><div><span class="hero-kicker">AI STUDIO · STORAGE</span><h2>Kho Lưu Trữ</h2><p>Nơi lưu kết quả AI thật, dự án edit và bản nháp có metadata đầy đủ.</p></div><button class="ai-primary" data-ai-action="upload">☁ Tải lên tài nguyên</button></div><div class="ai-toolbar"><input placeholder="Tìm tên file, project hoặc model..." /><select><option>Tất cả định dạng</option><option>Video</option><option>Ảnh</option><option>Dự án</option></select><select><option>Mới nhất</option><option>Cũ nhất</option></select></div><div class="ai-tabs">${tabs.map(([id, label]) => `<button class="ai-tab ${id === 'all' ? 'active' : ''}">${label}<span>${id === 'all' ? aiAssets.length : 0}</span></button>`).join('')}</div>${aiAssets.length ? `<div class="ai-asset-grid">${aiAssets.map((item) => `<article class="ai-asset-card"><div class="ai-asset-empty">${typeLabel(item.mediaType)}</div><strong>${esc(item.mediaName || item.title)}</strong><small>${esc(item.model || 'Model chưa ghi nhận')} · ${item.createdAt ? new Date(item.createdAt).toLocaleDateString('vi-VN') : '—'}</small></article>`).join('')}</div>` : aiUnavailable('Chưa có kết quả AI', 'Kho chỉ hiển thị video, ảnh hoặc dự án được tạo bởi model AI thật. Hiện chưa có AI provider được cấu hình.')}</div>`;
